import React, { useCallback, useRef, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID, TOP_HEADER_PX, LIVEBOARD_DARK_CUSTOMIZATIONS } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BG = '#F0EEE7';
const BRAND_GREEN = '#22D472';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 200px)`;

const VIEW_CHIPS = [
  { id: 'sales',   label: 'Sales',   tabId: '04f23f50-9b02-460f-b3cd-e635bd10d85c' },
  { id: 'finance', label: 'Finance', tabId: '2ac01db3-436a-4570-bf09-5d9d478bc81c' },
];

export default function DashboardHome() {
  const { hiddenActions, disabledActions } = useTier();
  const [selectedView, setSelectedView] = useState('sales');
  const selected = VIEW_CHIPS.find(v => v.id === selectedView)!;
  const embedRef = useRef<any>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Liveboard]', formatThoughtSpotEmbedError(err), err);
  }, []);

  return (
    <div style={{ backgroundColor: DARK, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* Dark header */}
      <div style={{ padding: '1.75rem 2.5rem 1rem' }}>
        <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: BRAND_GREEN, marginBottom: 6 }}>
          Maison
        </div>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: '#ffffff', margin: '0 0 1rem', letterSpacing: '-0.03em' }}>
          Analytics
        </h1>

        {/* View switcher pills */}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {VIEW_CHIPS.map(chip => {
            const isActive = chip.id === selectedView;
            return (
              <button
                key={chip.id}
                type="button"
                onClick={() => setSelectedView(chip.id)}
                style={{
                  padding: '7px 20px',
                  borderRadius: 20,
                  border: `1px solid ${isActive ? BRAND_GREEN : 'rgba(247,246,245,0.2)'}`,
                  background: isActive ? BRAND_GREEN : 'rgba(247,246,245,0.07)',
                  color: isActive ? '#ffffff' : 'rgba(255,255,255,0.75)',
                  fontSize: 13.5,
                  fontWeight: isActive ? 600 : 400,
                  cursor: 'pointer',
                  transition: 'all 0.15s ease',
                  whiteSpace: 'nowrap',
                  letterSpacing: '-0.01em',
                }}
              >
                {chip.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Embed card */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div style={{ backgroundColor: '#141414', borderRadius: 16, overflow: 'visible', minHeight: EMBED_MIN_H, boxShadow: '0 2px 32px rgba(0,0,0,0.5)' }}>
          <LiveboardEmbed
            ref={embedRef}
            key={selected.tabId}
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            activeTabId={selected.tabId}
            fullHeight
            hideTabPanel
            isLiveboardStylingAndGroupingEnabled
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            customizations={LIVEBOARD_DARK_CUSTOMIZATIONS}
            onError={onError}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
